void insertionSort(int[] tab) {
    for (int i = 1; i < tab.length; i++) {
        int biezacy = tab[i];
        int j = i - 1;
        while (j >= 0 && tab[j] > biezacy) {
            tab[j + 1] = tab[j]; // przesun w prawo
            j--;
        }
        tab[j + 1] = biezacy; // wstaw na wlasciwe miejsce
    }
}
// O(n^2) w najgorszym przypadku, ale O(n) dla JUZ posortowanych/prawie posortowanych danych!

void mergeSort(int[] tab, int lewy, int prawy) {
    if (lewy >= prawy) return; // 0 lub 1 element - juz posortowane
    int srodek = (lewy + prawy) / 2;
    mergeSort(tab, lewy, srodek);
    mergeSort(tab, srodek + 1, prawy);
    scal(tab, lewy, srodek, prawy);
}

void scal(int[] tab, int lewy, int srodek, int prawy) {
    int[] pomocnicza = new int[prawy - lewy + 1];
    int i = lewy, j = srodek + 1, k = 0;
    while (i <= srodek && j <= prawy) { // dwa wskazniki, jak w lekcji 3
        pomocnicza[k++] = (tab[i] <= tab[j]) ? tab[i++] : tab[j++];
    }
    while (i <= srodek) pomocnicza[k++] = tab[i++];
    while (j <= prawy) pomocnicza[k++] = tab[j++];
    System.arraycopy(pomocnicza, 0, tab, lewy, pomocnicza.length);
}

