void bubbleSort(int[] tab) {
    for (int i = 0; i < tab.length - 1; i++) {
        boolean zamieniono = false;
        for (int j = 0; j < tab.length - 1 - i; j++) {
            if (tab[j] > tab[j + 1]) { swap(tab, j, j + 1); zamieniono = true; }
        }
        if (!zamieniono) return;
    }
}

